[tool error]
{
  "ok": false,
  "name": "resolve_anchor",
  "error": {
    "type": "invalid_params",
    "message": "None is not of type 'string'",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "alignment": {
          "type": "string",
          "minLength": 1
        },
        "anchor": {
          "type": [
            "string",
            "number",
            "object"
          ],
          "description": "BEGIN | END | PI-n | PC-n | PT-n | MC-n | T-n | EQ-n | '18+00.00' | 1800, optionally '@offset' (ft, right +, e.g. 'PC-1@16', '18+00@25L'); or {ref|station, offset, region}. BC-n and EC-n, as a Caltrans plan letters them, are PC-n and PT-n"
        },
        "kind": {
          "enum": [
            "station",
            "pc",
            "pt",
            "pi",
            "mc",
            "pcc",
            "prc",
            "bearing",
            "begin",
            "end",
            "equation",
            "curve_data",
            "custom"
          ]
        },
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-001' or 'C-101'"
        },
        "viewport": {
          "type": "string",
          "minLength": 1
        },
        "side": {
          "enum": [
            "left",
            "right"
          ]
        },
        "label_offset": {
          "type": "number"
        },
        "rotation": {
          "enum": [
            "along",
            "perpendicular",
            "horizontal"
          ]
        },
        "content": {
          "type": "string"
        },
        "sheet": {
          "type": "string",
          "minLength": 1,
          "description": "for a referenced alignment: also say where the anchor falls on that sheet (on_sheet)"
        }
      },
      "required": [
        "anchor"
      ],
      "additionalProperties": false
    },
    "example": {
      "alignment": "ALIGN-1",
      "anchor": "PC-1"
    }
  }
}

[tool error]
{
  "ok": false,
  "name": "place_label",
