    "type": "invalid_params",
    "message": "Additional properties are not allowed ('sheet' was unexpected)",
    "hint": "params must match the schema; a valid example is included",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "space": {
          "type": "string",
          "minLength": 1,
          "description": "'model' (design space, US survey feet) or a sheet id/name (paper space, inches), e.g. 'SH-001' or 'C-101'"
        },
        "alignment": {
          "type": "string",
          "minLength": 1
        },
        "anchor": {
          "type": [
            "string",
            "number",
            "object"
          ],
          "description": "BEGIN | END | PI-n | PC-n | PT-n | MC-n | T-n | EQ-n | '18+00.00' | 1800, optionally '@offset' (ft, right +, e.g. 'PC-1@16', '18+00@25L'); or {ref|station, offset, region}. BC-n and EC-n, as a Caltrans plan letters them, are PC-n and PT-n"
        },
        "kind": {
          "enum": [
            "station",
            "pc",
            "pt",
            "pi",
            "mc",
            "pcc",
            "prc",
            "bearing",
            "begin",
            "end",
            "equation",
            "curve_data",
            "custom"
          ]
        },
        "content": {
          "type": "string",
          "description": "explicit text; omit to auto-generate from design data (recorded either way)"
        },
        "side": {
          "enum": [
            "left",
            "right"
          ]
        },
        "label_offset": {
          "type": "number",
          "minimum": 0,
          "description": "distance from the anchor point, feet in model / inches on sheets; default 16 ft / 0.32 in"
        },
        "rotation": {
          "enum": [
            "along",
            "perpendicular",
            "horizontal"
          ]
        },
        "height": {
          "type": "number",
          "exclusiveMinimum": 0,
          "description": "text height, feet in model / inches on sheets; default 8 ft / 0.10 in"
        },
        "style": {
          "type": "string",
          "minLength": 1
        },
        "halign": {
          "type": "string",
          "enum": [
            "left",
            "center",
            "right"
          ]
        },
        "valign": {
          "type": "string",
          "enum": [
            "bottom",
            "middle",
            "top"
          ]
        },
        "layer": {
          "type": "string",
          "minLength": 1
        },
        "color": {
          "type": "string",
          "description": "named CAD color (black, red, yellow, green, cyan, blue, magenta, gray, white) or '#RRGGBB'"
        },
        "linetype": {
          "type": "string",
          "enum": [
            "continuous",
            "dashed",
            "center",
            "hidden",
            "dot",
            "phantom"
          ]
        },
        "viewport": {
          "type": "string",
          "minLength": 1,
          "description": "sheet space only: viewport id/name carrying the anchor; default = the first viewport whose frame contains the point"
        }
      },
      "required": [
        "space",
        "anchor"
      ],
      "additionalProperties": false
    },
    "example": {
      "space": "model",
      "alignment": "ALIGN-1",
      "anchor": "PC-1"
    }
  },
  "warnings": []
}

